alter table public.page_visitor_posts add column if not exists content_type text not null default 'text', add column if not exists media jsonb not null default '[]'::jsonb, add column if not exists event_id uuid null references public.page_events(id) on delete set null;
alter table public.page_visitor_posts drop constraint if exists page_visitor_posts_content_check;
alter table public.page_visitor_posts add constraint page_visitor_posts_content_check check (char_length(trim(content)) <= 5000 and (char_length(trim(content)) >= 1 or jsonb_array_length(media) > 0 or event_id is not null));
alter table public.page_visitor_posts drop constraint if exists page_visitor_posts_content_type_check;
alter table public.page_visitor_posts add constraint page_visitor_posts_content_type_check check (content_type in ('text','image','video','document','event'));
create index if not exists idx_page_visitor_posts_page_created on public.page_visitor_posts(page_id,created_at desc);
create table if not exists public.page_visitor_post_likes(post_id uuid not null references public.page_visitor_posts(id) on delete cascade,user_id uuid not null references public.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(post_id,user_id));
create table if not exists public.page_visitor_post_comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.page_visitor_posts(id) on delete cascade,user_id uuid not null references public.users(id) on delete cascade,content text not null check(char_length(trim(content)) between 1 and 2000),is_hidden boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.page_visitor_post_shares(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.page_visitor_posts(id) on delete cascade,user_id uuid not null references public.users(id) on delete cascade,created_at timestamptz not null default now());
create index if not exists idx_page_visitor_post_comments_post on public.page_visitor_post_comments(post_id,created_at);
alter table public.page_visitor_post_likes enable row level security; alter table public.page_visitor_post_comments enable row level security; alter table public.page_visitor_post_shares enable row level security;
drop policy if exists page_visitor_post_likes_select on public.page_visitor_post_likes; create policy page_visitor_post_likes_select on public.page_visitor_post_likes for select using(exists(select 1 from public.page_visitor_posts p where p.id=post_id and p.status='published'));
drop policy if exists page_visitor_post_likes_insert on public.page_visitor_post_likes; create policy page_visitor_post_likes_insert on public.page_visitor_post_likes for insert with check(user_id=auth.uid() and exists(select 1 from public.page_visitor_posts p join public.page_followers f on f.page_id=p.page_id and f.user_id=auth.uid() where p.id=post_id and p.status='published'));
drop policy if exists page_visitor_post_likes_delete on public.page_visitor_post_likes; create policy page_visitor_post_likes_delete on public.page_visitor_post_likes for delete using(user_id=auth.uid() or current_user_has_page_permission((select page_id from public.page_visitor_posts where id=post_id),'manage_content'));
drop policy if exists page_visitor_post_comments_select on public.page_visitor_post_comments; create policy page_visitor_post_comments_select on public.page_visitor_post_comments for select using(exists(select 1 from public.page_visitor_posts p where p.id=post_id and p.status='published') and(not is_hidden or user_id=auth.uid() or current_user_has_page_permission((select page_id from public.page_visitor_posts where id=post_id),'manage_content')));
drop policy if exists page_visitor_post_comments_insert on public.page_visitor_post_comments; create policy page_visitor_post_comments_insert on public.page_visitor_post_comments for insert with check(user_id=auth.uid() and exists(select 1 from public.page_visitor_posts p join public.page_followers f on f.page_id=p.page_id and f.user_id=auth.uid() where p.id=post_id and p.status='published'));
drop policy if exists page_visitor_post_comments_delete on public.page_visitor_post_comments; create policy page_visitor_post_comments_delete on public.page_visitor_post_comments for delete using(user_id=auth.uid() or current_user_has_page_permission((select page_id from public.page_visitor_posts where id=post_id),'manage_content'));
drop policy if exists page_visitor_post_shares_select on public.page_visitor_post_shares; create policy page_visitor_post_shares_select on public.page_visitor_post_shares for select using(user_id=auth.uid() or exists(select 1 from public.page_visitor_posts p where p.id=post_id and current_user_has_page_permission(p.page_id,'view_analytics')));
drop policy if exists page_visitor_post_shares_insert on public.page_visitor_post_shares; create policy page_visitor_post_shares_insert on public.page_visitor_post_shares for insert with check(user_id=auth.uid() and exists(select 1 from public.page_visitor_posts p where p.id=post_id and p.status='published'));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('page-visitor-media','page-visitor-media',true,26214400,array['image/jpeg','image/png','image/webp','image/gif','video/mp4','video/quicktime','video/webm','application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document']) on conflict(id) do update set file_size_limit=26214400,allowed_mime_types=excluded.allowed_mime_types,public=true;
drop policy if exists page_visitor_post_media_insert on storage.objects; create policy page_visitor_post_media_insert on storage.objects for insert with check(bucket_id='page-visitor-media' and exists(select 1 from public.page_visitor_posts p join public.page_followers f on f.page_id=p.page_id and f.user_id=auth.uid() where p.id=((storage.foldername(name))[2])::uuid and p.page_id=((storage.foldername(name))[1])::uuid and p.author_id=auth.uid()));
drop policy if exists page_visitor_post_media_update on storage.objects; create policy page_visitor_post_media_update on storage.objects for update using(bucket_id='page-visitor-media' and exists(select 1 from public.page_visitor_posts p where p.id=((storage.foldername(name))[2])::uuid and(p.author_id=auth.uid() or current_user_has_page_permission(p.page_id,'manage_content'))));
drop policy if exists page_visitor_post_media_delete on storage.objects; create policy page_visitor_post_media_delete on storage.objects for delete using(bucket_id='page-visitor-media' and exists(select 1 from public.page_visitor_posts p where p.id=((storage.foldername(name))[2])::uuid and(p.author_id=auth.uid() or current_user_has_page_permission(p.page_id,'manage_content'))));
